import hou, math

def wpos(path, f):
    n = hou.node(path)
    return hou.Vector3(0, 0, 0) * n.worldTransformAtTime(hou.frameToTime(f))

def project(campath, P, f):
    cam = hou.node(campath)
    t = hou.frameToTime(f)
    m = cam.worldTransformAtTime(t).inverted()
    p = hou.Vector3(P) * m
    if p[2] >= 0:
        return None
    foc = cam.evalParmAtFrame if False else None
    focal = cam.parm('focal').evalAtTime(t)
    ap = cam.parm('aperture').evalAtTime(t)
    rx = cam.parm('resx').evalAtTime(t); ry = cam.parm('resy').evalAtTime(t)
    sx = focal * p[0] / (-p[2]) / ap + 0.5
    sy = focal * p[1] / (-p[2]) / (ap * ry / rx) + 0.5
    return (sx, sy)

def inframe(campath, P, f, margin=0.0):
    s = project(campath, P, f)
    if s is None:
        return False
    return margin <= s[0] <= 1 - margin and margin <= s[1] <= 1 - margin

