import hou, math

FPS = 24.0
F0, F1 = 1, 264
FR = list(range(F0, F1 + 1))

def clamp(x, a=0.0, b=1.0):
    return max(a, min(b, x))

def ss(x):
    x = clamp(x)
    return x * x * x * (x * (x * 6 - 15) + 10)

def lerp(a, b, t):
    return a + (b - a) * t

def V(*a):
    return hou.Vector3(*a)

def key_parm(parm, values):
    """values: dict frame->value; linear per-frame keys"""
    parm.deleteAllKeyframes()
    keys = []
    for f in sorted(values):
        k = hou.Keyframe()
        k.setFrame(f)
        k.setValue(values[f])
        k.setExpression('linear()', hou.exprLanguage.Hscript)
        keys.append(k)
    parm.setKeyframes(keys)

g = hou.node('/obj/girl')
hc = hou.node('/obj/hand_contact')
body = hou.node('/obj/butterfly/CTRL_body')
wl = hou.node('/obj/butterfly/CTRL_wing_L')
wr = hou.node('/obj/butterfly/CTRL_wing_R')
headbone = hou.node('/obj/girl/rig_bone_head')

# ---------------------------------------------------------------- clear previous anim
for pn in ['ikwristlefttranslatex', 'ikwristlefttranslatey', 'ikwristlefttranslatez',
           'ikwristleftrotatex', 'ikwristleftrotatey', 'ikwristleftrotatez',
           'headrotatex', 'headrotatey', 'headrotatez']:
    g.parm(pn).deleteAllKeyframes()
for pn in ['tx', 'ty', 'tz', 'rx', 'ry', 'rz']:
    body.parm(pn).deleteAllKeyframes()

# ---------------------------------------------------------------- base values (from base scene)
T0 = V(-0.31513106711217626, 0.004341544089813493, 0.1780316453785062)
R0 = V(-30.0, -60.0, 0.0)
W0 = V(0.087, 0.547, 0.153)          # wrist world rest
W1 = V(0.13, 0.785, 0.22)            # wrist world presenting
R1 = V(-50.0, -30.0, 20.0)
D = W1 - W0

# ---------------------------------------------------------------- left hand
def hand_w(f):
    return ss((f - 56) / 48.0) * (1 - ss((f - 244) / 40.0))

hand_vals = {n: {} for n in 'xyz'}
hand_rot = {n: {} for n in 'xyz'}
for f in range(F0, F1 + 6):
    w = hand_w(f)
    for i, n in enumerate('xyz'):
        hand_vals[n][f] = T0[i] + D[i] * w
        hand_rot[n][f] = R0[i] + (R1[i] - R0[i]) * w
for n in 'xyz':
    key_parm(g.parm('ikwristlefttranslate' + n), hand_vals[n])
    key_parm(g.parm('ikwristleftrotate' + n), hand_rot[n])

# ---------------------------------------------------------------- fingers (both hands, constant relaxed curl)
curl = {'index': 5.0, 'middle': 7.0, 'ring': 9.0, 'little': 11.0}
for side in ['left', 'right']:
    for fn, a in curl.items():
        g.parm('%s%s1rotatex' % (side, fn)).set(a)
        g.parm('%s%s2rotate' % (side, fn)).set(a)
        g.parm('%s%s3rotate' % (side, fn)).set(a)

# ---------------------------------------------------------------- sample hand_contact
H = {}; HY = {}; HM = {}
for f in range(F0 - 4, F1 + 6):
    m = hc.worldTransformAtTime(hou.frameToTime(f))
    H[f] = V(0, 0, 0) * m
    HY[f] = (V(0, 1, 0) * m.extractRotationMatrix3()).normalized()

head_origin = {}
for f in range(F0 - 4, F1 + 6):
    head_origin[f] = V(0, 0, 0) * headbone.worldTransformAtTime(hou.frameToTime(f))

UP = V(0, 1, 0)
HOVER = 0.12
LAND = 0.008

# ---------------------------------------------------------------- butterfly base flight path (Hermite)
wps = [(1, V(1.05, 1.22, 0.78)), (20, V(0.80, 1.17, 0.64)), (40, V(0.50, 1.11, 0.47)),
       (58, V(0.24, 1.05, 0.31)), (73, V(0.06, 0.995, 0.19)), (87, V(0.09, 0.95, 0.25)),
       (100, H[100] + UP * HOVER)]

def tangents(pts):
    tg = []
    for i in range(len(pts)):
        if i == 0:
            tg.append((pts[1][1] - pts[0][1]) * (1.0 / (pts[1][0] - pts[0][0])))
        elif i == len(pts) - 1:
            tg.append(V(0, 0, 0))
        else:
            tg.append((pts[i + 1][1] - pts[i - 1][1]) * (1.0 / (pts[i + 1][0] - pts[i - 1][0])))
    return tg

TG = tangents(wps)

def hermite(f):
    for i in range(len(wps) - 1):
        fa, pa = wps[i]; fb, pb = wps[i + 1]
        if fa <= f <= fb or (i == 0 and f < fa):
            h = fb - fa
            t = (f - fa) / float(h)
            t2, t3 = t * t, t * t * t
            h00 = 2 * t3 - 3 * t2 + 1; h10 = t3 - 2 * t2 + t
            h01 = -2 * t3 + 3 * t2; h11 = t3 - t2
            return pa * h00 + TG[i] * (h10 * h) + pb * h01 + TG[i + 1] * (h11 * h)
    return wps[-1][1]

def wobble(f, ampv, ampl):
    t = (f - 1) / FPS
    y = ampv * (0.85 * math.sin(2 * math.pi * 1.5 * t + 0.4) + 0.15 * math.sin(2 * math.pi * 2.6 * t + 1.3))
    lx = ampl * math.sin(2 * math.pi * 1.1 * t + 0.9)
    lz = ampl * 0.7 * math.sin(2 * math.pi * 0.8 * t + 2.1)
    return V(lx, y, lz)

FLY_DIR = V(0.65, 0.55, 0.52).normalized()

def bpos(f):
    if f <= 100:
        env = 1.0 - ss((f - 88) / 12.0)
        p = hermite(f) + wobble(f, 0.028 * env, 0.02 * env)
        # small residual hover bob blending in
        t = (f - 1) / FPS
        p += V(0, 0.003 * math.sin(2 * math.pi * 1.6 * t) * (1 - env), 0)
        return p
    if f <= 112:
        t = (f - 1) / FPS
        return H[f] + UP * HOVER + V(0, 0.003 * math.sin(2 * math.pi * 1.6 * t), 0)
    if f <= 132:
        s = ss((f - 112) / 20.0)
        t = (f - 1) / FPS
        bob = V(0, 0.003 * math.sin(2 * math.pi * 1.6 * t) * (1 - s), 0)
        return H[f] + UP * HOVER * (1 - s) + HY[f] * LAND * s + bob
    if f <= 216:
        return H[f] + HY[f] * LAND
    # takeoff
    s = ss((f - 217) / 14.0)
    t = (f - 1) / FPS
    p = H[f] + HY[f] * LAND * (1 - s) + UP * 0.15 * s + V(0, 0.004 * math.sin(2 * math.pi * 1.4 * t) * s, 0)
    away = ss((f - 236) / 40.0) * 0.62
    return p + FLY_DIR * away

